import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'package:http/http.dart' as http;

const ink=Color(0xFF090A0D), panel=Color(0xFF14171D), gold=Color(0xFFE6B84D);
const apiBase=String.fromEnvironment('API_BASE_URL', defaultValue:'https://YOUR-API-DOMAIN.example.com');
const secureStorage=FlutterSecureStorage();
void main()=>runApp(const GreatArkApp());
class Api {
 static String? token;
 static Future<Map<String,dynamic>> login(String email,String password) async {
  final r=await http.post(Uri.parse('$apiBase/api/auth/login'),headers:{'Content-Type':'application/json'},body:jsonEncode({'email':email,'password':password})).timeout(const Duration(seconds:15));
  final body=jsonDecode(r.body) as Map<String,dynamic>; if(r.statusCode!=200) throw Exception(body['error']??'Login gagal');
  token=body['token'] as String; await secureStorage.write(key:'token',value:token); await secureStorage.write(key:'user',value:jsonEncode(body['user'])); return body['user'] as Map<String,dynamic>;
 }
 static Future<List<dynamic>> getList(String resource) async { final t=token??await secureStorage.read(key:'token'); if(t==null) throw Exception('Silakan login kembali'); final r=await http.get(Uri.parse('$apiBase/api/$resource'),headers:{'Authorization':'Bearer $t'}).timeout(const Duration(seconds:15)); if(r.statusCode==401) throw Exception('Sesi berakhir, silakan login ulang'); if(r.statusCode!=200) throw Exception('Gagal memuat data dari server'); return jsonDecode(r.body) as List<dynamic>; }
 static Future<void> logout() async { token=null; await secureStorage.delete(key:'token'); await secureStorage.delete(key:'user'); }
}
class GreatArkApp extends StatelessWidget {const GreatArkApp({super.key}); @override Widget build(BuildContext context)=>MaterialApp(title:'SSB Great Ark',debugShowCheckedModeBanner:false,theme:ThemeData(useMaterial3:true,brightness:Brightness.dark,scaffoldBackgroundColor:ink,colorScheme:ColorScheme.fromSeed(seedColor:gold,brightness:Brightness.dark),cardColor:panel),home:const AuthGate());}
class AuthGate extends StatefulWidget {const AuthGate({super.key}); @override State<AuthGate> createState()=>_AuthGateState();}
class _AuthGateState extends State<AuthGate>{bool loading=true,hasToken=false; @override void initState(){super.initState();_check();} Future<void> _check()async{Api.token=await secureStorage.read(key:'token');if(mounted)setState(() { hasToken=Api.token!=null; loading=false; });} @override Widget build(BuildContext context)=>loading?const Scaffold(body:Center(child:CircularProgressIndicator(color:gold))):hasToken?HomeScreen(onLogout:(){setState(()=>hasToken=false);Api.logout();}):LoginScreen(onLogin:(){setState(()=>hasToken=true);});}
class LoginScreen extends StatefulWidget {final VoidCallback onLogin;const LoginScreen({super.key,required this.onLogin});@override State<LoginScreen> createState()=>_LoginScreenState();}
class _LoginScreenState extends State<LoginScreen>{final email=TextEditingController(),password=TextEditingController();bool busy=false;String? error;Future<void> submit()async{setState(() { busy=true; error=null; });try{await Api.login(email.text.trim(),password.text);if(mounted)widget.onLogin();}catch(e){setState(()=>error=e.toString().replaceFirst('Exception: ',''));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext context)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:420),child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Icon(Icons.sports_soccer,color:gold,size:72),const SizedBox(height:12),const Text('SSB GREAT ARK',textAlign:TextAlign.center,style:TextStyle(fontSize:25,fontWeight:FontWeight.w900,letterSpacing:2)),const SizedBox(height:8),const Text('Masuk untuk terhubung ke data SSB',textAlign:TextAlign.center,style:TextStyle(color:Colors.white60)),const SizedBox(height:28),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email',border:OutlineInputBorder(),prefixIcon:Icon(Icons.email_outlined))),const SizedBox(height:14),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Kata sandi',border:OutlineInputBorder(),prefixIcon:Icon(Icons.lock_outline))),if(error!=null)Padding(padding:const EdgeInsets.only(top:12),child:Text(error!,style:const TextStyle(color:Colors.redAccent))),const SizedBox(height:20),FilledButton(onPressed:busy?null:submit,style:FilledButton.styleFrom(backgroundColor:gold,foregroundColor:ink,padding:const EdgeInsets.all(16)),child:busy?const CircularProgressIndicator():const Text('MASUK'))])))));}}
class HomeScreen extends StatefulWidget {final VoidCallback onLogout;const HomeScreen({super.key,required this.onLogout});@override State<HomeScreen> createState()=>_HomeScreenState();}
class _HomeScreenState extends State<HomeScreen>{int tab=0;List<dynamic> schedules=[],players=[],notifications=[];bool loading=true;String? error;@override void initState(){super.initState();load();}Future<void> load()async{setState(() { loading=true; error=null; });try{final results=await Future.wait([Api.getList('schedule'),Api.getList('players'),Api.getList('notifications')]);if(mounted)setState(() { schedules=results[0]; players=results[1]; notifications=results[2]; });}catch(e){if(mounted)setState(()=>error=e.toString().replaceFirst('Exception: ',''));}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext context){final title=['Beranda','Jadwal','Pemain','Info'][tab];return Scaffold(appBar:AppBar(backgroundColor:ink,title:Text('GREAT ARK · $title',style:const TextStyle(fontWeight:FontWeight.w800,letterSpacing:1)),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh)),IconButton(onPressed:widget.onLogout,icon:const Icon(Icons.logout))]),body:loading?const Center(child:CircularProgressIndicator(color:gold)):error!=null?Center(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[Text(error!,textAlign:TextAlign.center),const SizedBox(height:12),FilledButton(onPressed:load,child:const Text('Coba lagi'))]))):RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[if(tab==0)...[Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xFF282216),panel]),borderRadius:BorderRadius.circular(18),border:Border.all(color:const Color(0xFF5E4B25))),child:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('SEKOLAH SEPAK BOLA',style:TextStyle(color:gold,letterSpacing:2,fontSize:11)),SizedBox(height:8),Text('Bersama Membangun Generasi Sepak Bola',style:TextStyle(fontSize:23,fontWeight:FontWeight.w800)),SizedBox(height:8),Text('Data terhubung ke server Great Ark.',style:TextStyle(color:Colors.white70))]),),const SizedBox(height:16),Row(children:[Expanded(child:_Metric(title:'Pemain',value:'${players.length}')),const SizedBox(width:10),Expanded(child:_Metric(title:'Jadwal',value:'${schedules.length}'))]),const SizedBox(height:22),const Text('JADWAL TERBARU',style:TextStyle(color:gold,fontWeight:FontWeight.bold)),...schedules.take(4).map((s)=>_DataTile(title:'${s['title']??'Latihan'}',subtitle:'${s['group']??''} · ${s['date']??''} · ${s['place']??''}',icon:Icons.calendar_month)),const SizedBox(height:16),const Text('PENGUMUMAN',style:TextStyle(color:gold,fontWeight:FontWeight.bold)),...notifications.take(3).map((n)=>_DataTile(title:'${n['title']??''}',subtitle:'${n['message']??''}',icon:Icons.campaign_outlined))],if(tab==1)...schedules.map((s)=>_DataTile(title:'${s['title']??'Latihan'}',subtitle:'${s['group']??''} · ${s['date']??''} · ${s['place']??''}',icon:Icons.calendar_month)),if(tab==2)...players.map((p)=>_DataTile(title:'${p['name']??'Pemain'}',subtitle:'${p['group']??''} · ${p['status']??''}',icon:Icons.person_outline)),if(tab==3)...notifications.map((n)=>_DataTile(title:'${n['title']??''}',subtitle:'${n['message']??''}',icon:Icons.campaign_outlined))])) ,bottomNavigationBar:NavigationBar(backgroundColor:panel,selectedIndex:tab,onDestinationSelected:(v)=>setState(() { tab=v; }),destinations:const [NavigationDestination(icon:Icon(Icons.home_outlined),label:'Beranda'),NavigationDestination(icon:Icon(Icons.calendar_month),label:'Jadwal'),NavigationDestination(icon:Icon(Icons.sports_soccer),label:'Pemain'),NavigationDestination(icon:Icon(Icons.notifications_none),label:'Info')]);}}
class _Metric extends StatelessWidget{final String title,value;const _Metric({required this.title,required this.value});@override Widget build(BuildContext context)=>Card(color:panel,child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(color:Colors.white60)),const SizedBox(height:8),Text(value,style:const TextStyle(color:gold,fontWeight:FontWeight.w900,fontSize:26))])));}
class _DataTile extends StatelessWidget{final String title,subtitle;final IconData icon;const _DataTile({required this.title,required this.subtitle,required this.icon});@override Widget build(BuildContext context)=>Card(color:panel,child:ListTile(leading:Icon(icon,color:gold),title:Text(title),subtitle:Text(subtitle),isThreeLine:subtitle.length>50));}
